contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public {
        // owner() is not a public getter on C; the only observable effect of XBornID()
        // is that the caller (the InvMutTest contract, which deployed c) receives exactly
        // totalDistributed tokens at the end of the initialization.
        c.XBornID();
        assert(c.balanceOf(address(this)) == 200000000e18);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _from, address _to, uint256 _amount) public {
        require(_to != address(0));
        require(_from != address(0));

        uint256 beforeFromBal = c.balanceOf(_from);
        uint256 beforeToBal = c.balanceOf(_to);
        uint256 beforeAllow = c.allowance(_from, address(this));
        uint256 beforeTotalSupply = c.totalSupply();

        bool reverted;
        try c.transferFrom(_from, _to, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterFromBal = c.balanceOf(_from);
        uint256 afterToBal = c.balanceOf(_to);
        uint256 afterAllow = c.allowance(_from, address(this));
        uint256 afterTotalSupply = c.totalSupply();

        assert(
            reverted ||
            (afterAllow == beforeAllow - _amount &&
             afterFromBal == beforeFromBal - _amount &&
             afterToBal == beforeToBal + _amount &&
             afterTotalSupply == beforeTotalSupply)
        );
    }
}

contract InvMutTest {
    C c;

