    function run(address _from, uint256 _amount) public {
        require(_from != address(0));
        require(c.balanceOf(_from) >= _amount);
        require(c.allowance(_from, address(this)) >= _amount);

        uint256 beforeAllow = c.allowance(_from, address(this));

        c.transferFrom(_from, address(this), _amount);

        uint256 afterAllow = c.allowance(_from, address(this));

        assert(afterAllow == beforeAllow - _amount);
    }
}

