contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _from, address _spender, uint256 _allowance, uint256 _amount) public {
        require(_from != address(0));
        require(_spender != address(0));
        require(_from != _spender);
        require(_spender == address(this));

        c.approve(address(this), _allowance);
        uint256 beforeAllowance = c.allowance(_from, address(this));
        require(beforeAllowance == _allowance);

        bool success;
        try c.transferFrom(_from, address(this), _amount) returns (bool ok) {
            success = ok;
        } catch {
            success = false;
        }

        uint256 afterAllowance = c.allowance(_from, address(this));

        if (success) {
            assert(afterAllowance == beforeAllowance - _amount);
        } else {
            assert(afterAllowance == beforeAllowance);
        }
    }
}

