contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool first) public {
        if (first) {
            bool ok = c.finishDistribution();
            assert(ok == true && c.distributionFinished() == true);
        } else {
            c.finishDistribution();
            bool reverted;
            try c.finishDistribution() { reverted = false; } catch { reverted = true; }
            assert(reverted == true && c.distributionFinished() == true);
        }
    }
}

