contract InvMutTest {
    C c;
    address originalOwner;

    constructor(C _c) {
        c = _c;
        originalOwner = msg.sender; // the deployer of c, also c's owner
    }

    function run(uint256 dummy) public {
        require(dummy == dummy);
        require(msg.sender != originalOwner, "caller is owner; use a non-owner caller");

        bool before = c.distributionFinished();

        bool reverted;
        try c.finishDistribution() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool after = c.distributionFinished();

        assert(reverted && before == after);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 dummy) public {
        require(dummy == dummy);

        bool before = c.distributionFinished();
        require(!before, "distribution already finished before call");

        bool reverted;
        try c.finishDistribution() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool current = c.distributionFinished();

        assert(reverted && !current);
    }
}

